mapper.sql:
WHERE IS_DELETED = 'N'
AND STATUS = #{assetStatus}
AND CATEGORY = #{category}
AND COMPANY = #{company}
AND UPPER(CATEGORY) LIKE UPPER(#{keywordLike}) ESCAPE '\'
AND UPPER(COMPANY) LIKE UPPER(#{keywordLike}) ESCAPE '\'
AND UPPER(NAME) LIKE UPPER(#{keywordLike}) ESCAPE '\'
AND UPPER(STATUS) LIKE UPPER(#{keywordLike}) ESCAPE '\'
AND ( UPPER(CATEGORY) LIKE UPPER(#{keywordLike}) ESCAPE '\' OR UPPER(COMPANY) LIKE UPPER(#{keywordLike}) ESCAPE '\' OR UPPER(NAME) LIKE UPPER(#{keywordLike}) ESCAPE '\' OR UPPER(STATUS) LIKE UPPER(#{keywordLike}) ESCAPE '\' )

mapper.select:
SELECT COUNT(*) FROM ( SELECT a.asset_id, COALESCE(( SELECT r.address_city FROM reservation r WHERE r.asset_id = a.asset_id AND r.status = 'APPROVED' FETCH FIRST 1 ROWS ONLY ), '농촌진흥청') AS location FROM asset a
) t
AND t.location = #{location}
AND UPPER(t.location) LIKE UPPER(#{keywordLike}) ESCAPE '\'

SELECT * FROM ( SELECT t.*, ROW_NUMBER() OVER (ORDER BY t.created_at DESC) rn FROM ( SELECT a.*, COALESCE(( SELECT r.address_city FROM reservation r WHERE r.asset_id = a.asset_id AND r.status = 'APPROVED' FETCH FIRST 1 ROWS ONLY ), '농촌진흥청') AS location FROM asset a
) t
AND t.location = #{location}
AND UPPER(t.location) LIKE UPPER(#{keywordLike}) ESCAPE '\'
) WHERE rn BETWEEN #{startRow} AND #{endRow} ORDER BY rn

SELECT *
FROM ASSET
WHERE IS_DELETED = 'N'

    AND STATUS = #{assetStatus}


    AND CATEGORY = #{category}


    AND COMPANY = #{company}

ORDER BY CREATED_AT DESC

mapper.update:
